(() => {
'use strict';
if(location.protocol==='http:'&&!['localhost','127.0.0.1','[::1]'].includes(location.hostname)){location.replace('https://'+location.host+location.pathname+location.search+location.hash);return;}
const $=s=>document.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={folder:'M3 7h7l3 3h8v10H3z M3 7V4h7l3 3h8v3',file:'M6 3h8l4 4v14H6z M14 3v5h4 M9 12h6 M9 16h6',plus:'M12 5v14 M5 12h14',arrow:'M5 12h14 M13 6l6 6-6 6',search:'M20 20l-5-5 M17 10a7 7 0 1 1-14 0 7 7 0 0 1 14 0',bell:'M5 17h14l-2-3V9a5 5 0 0 0-10 0v5z M10 21h4',lock:'M5 10h14v11H5z M8 10V7a4 4 0 0 1 8 0v3 M12 14v3',chat:'M4 4h16v12H9l-5 4z M8 8h8 M8 12h5',person:'M8 7a4 4 0 1 0 8 0 4 4 0 0 0-8 0 M4 21v-3a8 6 0 0 1 16 0v3',download:'M12 3v12 M7 10l5 5 5-5 M4 16v5h16v-5',heart:'M12 21 3 12C-2 5 8 1 12 7c4-6 14-2 9 5z',bookmark:'M6 3h12v18l-6-4-6 4z',compass:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0 M15 8l-2 6-5 2 2-6z',clock:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0 M12 7v5l3 2',trophy:'M7 3h10v8a5 5 0 0 1-10 0z M7 5H3v5a4 4 0 0 0 4 4 M17 5h4v5a4 4 0 0 1-4 4 M12 16v5 M8 21h8'};
const icon=(n,size=20)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[n]||paths.folder}"/></svg>`;
const navShapes={home:'<path d="M5 4h14a2 2 0 0 1 2 2v10a2 2 0 0 1-2 2H9l-5 3V6a2 2 0 0 1 1-2z"/><circle cx="8" cy="11" r="1.3" fill="currentColor" stroke="none"/><circle cx="12.5" cy="11" r="1.3" fill="currentColor" stroke="none"/><circle cx="17" cy="11" r="1.3" fill="currentColor" stroke="none"/>',discover:'<rect x="3" y="3" width="7" height="7" rx="1.5" fill="currentColor" stroke="none"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5" fill="currentColor" stroke="none"/>',creators:'<circle cx="12" cy="7" r="4" fill="currentColor" stroke="none"/><path d="M4 21v-2a8 6 0 0 1 16 0v2z"/><path d="M8 18h8v3H8z" fill="currentColor" stroke="none"/>',events:'<path d="M7 3h10v8a5 5 0 0 1-10 0z" fill="currentColor" stroke="none"/><path d="M7 5H3v4a4 4 0 0 0 4 4m10-8h4v4a4 4 0 0 1-4 4M12 16v4"/><rect x="7" y="20" width="10" height="2" rx="1" fill="currentColor" stroke="none"/>',archive:'<rect x="3" y="3" width="18" height="18" rx="4"/><circle cx="9" cy="9" r="2.2" fill="currentColor" stroke="none"/><path d="M6 16a3 3 0 0 1 6 0"/><path d="M15 8h3m-3 4h3m-3 4h3"/>'};
const navIcon=n=>`<svg class="nav-symbol" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${navShapes[n]||navShapes.home}</svg>`;
const art=`<div class="hero-art"><svg viewBox="0 0 270 230" fill="none" aria-hidden="true"><path d="M26 211h213" stroke="#729a78" stroke-width="2" stroke-dasharray="3 7"/><rect x="89" y="20" width="131" height="151" rx="12" transform="rotate(11 89 20)" fill="#dfe7c5" stroke="#3d6246" stroke-width="2"/><rect x="56" y="39" width="136" height="147" rx="12" transform="rotate(-10 56 39)" fill="#fff" stroke="#3d6246" stroke-width="2"/><path d="m80 69 66-11M82 80l42-7" stroke="#94ac88" stroke-width="5" stroke-linecap="round"/><path d="M34 108h68l16 16h105v75H34z" fill="#426c4d" stroke="#284d36" stroke-width="2" stroke-linejoin="round"/><path d="M27 138h205l-12 67H39z" fill="#c5e68b" stroke="#284d36" stroke-width="2" stroke-linejoin="round"/><rect x="101" y="159" width="61" height="25" rx="7" fill="#fff" stroke="#4b6d47" stroke-width="1.5"/><path d="M115 171h31" stroke="#4b6d47" stroke-width="3" stroke-linecap="round"/><path d="m229 53 3 11 11 3-11 3-3 11-3-11-11-3 11-3z" fill="#fff" stroke="#426c4d" stroke-width="1.5"/><circle cx="34" cy="83" r="5" fill="#c5e68b" stroke="#426c4d" stroke-width="1.5"/></svg></div>`;
function readLegacy(){try{const x=JSON.parse(localStorage.getItem('super-ai-youth-v1')||'{}');return {profile:x.profile||{},works:Array.isArray(x.works)?x.works:[],draft:x.draft||null};}catch{return {profile:{},works:[],draft:null};}}
let legacy=readLegacy();
const state={user:null,projects:[],files:[],posts:[],feed:{projects:[],posts:[]},usage:{used:0,limit:104857600},ready:false,local:localStorage.getItem('archive-local-mode')==='1',route:'',seq:0};
const chatState={chats:[],unreadTotal:0,current:null,messages:[],olderCursor:null,listError:'',drafts:new Map(),timer:null,generation:0,sending:false,loadingOlder:false,searchSeq:0,searchTimer:null,sendingKeys:new Set()};
const expandedPosts=new Set();
const messageState={baseRoute:'home',baseRendered:false,open:false,full:false,baseContent:null};
const notificationState={owner:null,items:[],unreadTotal:0,error:''};
const composeState={owner:null,kind:'update',projectId:'',body:''};
function resetCompose(){Object.assign(composeState,{owner:state.user?.id||null,kind:'update',projectId:'',body:''});}
function resetChatSession(){resetCompose();stopChatPolling();chatState.chats=[];chatState.unreadTotal=0;chatState.current=null;chatState.messages=[];chatState.olderCursor=null;chatState.listError='';chatState.drafts.clear();chatState.sending=false;chatState.sendingKeys.clear();Object.assign(notificationState,{owner:null,items:[],unreadTotal:0,error:''});updateChatBadge();}
const personal=()=>state.user?.profile||(state.local?legacy.profile:{});
const works=()=>state.user?state.projects:legacy.works.map((p,i)=>({...p,id:`local-${i}`,visibility:'private',review:'private'}));
const safeURL=v=>{try{const u=new URL(v);return /^https?:$/.test(u.protocol)?u.href:'';}catch{return '';}};
const date=v=>v?new Date(typeof v==='number'?v*1000:v).toLocaleDateString('zh-CN',{month:'short',day:'numeric'}):'本机记录';
const bytes=n=>n<1048576?`${Math.round(n/1024)} KB`:`${(n/1048576).toFixed(1)} MB`;
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),3800);}
async function api(p,method='GET',data){const ctl=new AbortController(),timer=setTimeout(()=>ctl.abort(),15000);try{const r=await fetch(`api${p}`,{method,credentials:'same-origin',cache:'no-store',headers:{'Content-Type':'application/json','X-Archive-Client':'1'},body:data===undefined?undefined:JSON.stringify(data),signal:ctl.signal});const d=await r.json().catch(()=>({error:'服务暂时不可用，请稍后重试。'}));if(!r.ok)throw Error(d.error||'操作未完成');return d;}catch(e){if(e.name==='AbortError')throw Error('连接超时，保存结果未确认，请刷新检查后再重试。');throw e;}finally{clearTimeout(timer);}}
async function refresh(){if(!state.user)return;const [m,p,f,s]=await Promise.all([api('/me'),api('/projects'),api('/files'),api('/posts')]);state.user=m.user;state.usage=m.usage;state.projects=p.projects;state.files=f.files;state.posts=s.posts;}
function saveLocal(){legacy.draft=readLegacy().draft;localStorage.setItem('super-ai-youth-v1',JSON.stringify(legacy));}
function nav(r){if(location.hash==='#'+r)render();else location.hash=r;}
const btn=(label,action,cls='',id='')=>`<button class="btn ${cls}" data-action="${action}" ${id?`data-id="${esc(id)}"`:''}>${label}</button>`;
const heading=(title,desc,actions='')=>`<div class="page-heading"><div><h1>${title}</h1>${desc?`<p class="muted">${desc}</p>`:''}</div><div class="action-row">${actions}</div></div>`;
const demoUI=(method,...args)=>window.DiscoveryDemos?.[method]?.(...args)||'';
const empty=(title,desc,action='',sym='folder')=>`<div class="empty-state"><div class="empty-icon">${icon(sym,30)}</div><h3>${title}</h3><p>${desc}</p>${action}</div>`;
const tabs=(base,items,active)=>`<nav class="subtabs" aria-label="内容分类">${items.map(([key,title])=>`<a href="#${base}${key?'/'+key:''}" ${key===active?'aria-current="page"':''}>${title}</a>`).join('')}</nav>`;
const tag=p=>p.visibility==='public'?`<span class="tag ${p.review==='approved'?'green':'amber'}">${{approved:'已公开',pending:'待审核',rejected:'未通过审核'}[p.review]||'待审核'}</span>`:`<span class="tag">仅自己</span>`;
function header(){
const context=messageState.open||state.route.split(/[/?]/)[0]==='messages'?messageState.baseRoute:state.route,p=context.split(/[/?]/)[0],mine=context==='discover/bookmarks'||p==='my-posts',demoPage=context.split('/')[1],active=p==='demo'?({project:'discover',creator:'creators',post:'home',event:'events'}[demoPage]||'home'):mine?'archive':p==='home'||p==='search'?'home':['discover','shared'].includes(p)?'discover':['creators','public'].includes(p)?'creators':p==='events'?'events':p==='compose'?'home':'archive';
document.body.dataset.homeVisual=String(p==='home'&&!messageState.full);
document.querySelectorAll('[data-nav]').forEach(a=>{a.removeAttribute('aria-current');if(a.dataset.nav===active)a.setAttribute('aria-current','page');const oldIcon=a.querySelector('svg');if(!oldIcon?.classList.contains('nav-symbol')){oldIcon?.remove();a.insertAdjacentHTML('afterbegin',navIcon(a.dataset.nav));}});
updateChatBadge();$('#notice-link').innerHTML=icon('bell')+'<span>消息通知</span>';$('#account-link').innerHTML='<span class="avatar tiny">'+esc((personal().name||'我').slice(0,1))+'</span><span>个人资料</span>';
$('#connection-note').hidden=state.ready;$('#connection-note').className='notice warning';$('#connection-note').textContent='账号服务暂未连接，登录和保存不可用。旧浏览器资料仍保留。';}

function sidebar(){const p=personal(),list=works();return `<aside class="aside-column"><section class="card profile-card"><div class="profile-top"><span class="avatar large">${esc((p.name||'我').slice(0,1))}</span><div><h3>${esc(p.name||'你的创作者档案')}</h3><span class="tag green">${state.user?'创作者':state.local?'本机试用':'尚未登录'}</span></div></div><p class="profile-blurb">${esc(p.bio||'写下做过的作品、擅长的事，逐步整理成自己的档案。')}</p>${list.length?`<div class="profile-counts"><div><strong>${list.length}</strong><span>件已保存作品</span></div><div><strong>${list.filter(w=>w.review==='approved').length}</strong><span>件公开作品</span></div></div>`:''}<a class="btn wide" href="#${state.user||state.local?'profile':'login'}">${state.user||state.local?'编辑个人档案':'登录并保存档案'} ${icon('arrow',16)}</a></section><section class="card tight"><div class="storage-head"><h3>我的资料空间</h3>${icon('folder',18)}</div><div class="storage-bar"><span style="width:${Math.min(100,state.usage.used/state.usage.limit*100)}%"></span></div><p class="small-text muted">${state.user?`${bytes(state.usage.used)} / ${bytes(state.usage.limit)}`:'登录后可保存作品附件'}</p><p class="small-text muted">单个文件最多 10 MB，附件仅自己可见。</p></section><section class="card tight"><h3>常用工具</h3><div class="side-links"><a href="#prepare">生成参赛建议 ${icon('arrow',16)}</a><button data-action="export-html">导出作品展示页 ${icon('download',16)}</button><a href="#credential">制作凭证草稿 ${icon('arrow',16)}</a></div></section><div class="side-note"><h3>公开由你决定</h3><p>新作品默认私密。准备好再提交公开，私人附件不会跟着发布。</p></div></aside>`;}
function workCard(p,i=0,shared=false){return '<article class="card work-card"><a href="#'+(shared?'shared':'project')+'/'+encodeURIComponent(p.id)+'"><div class="work-cover tone-'+i%4+'"><span class="cover-title">'+esc((p.tech||'创作作品').split(/[,，、]/)[0].slice(0,12))+'</span><span class="cover-symbol" aria-hidden="true">'+['✳','◇','✦','⌘'][i%4]+'</span></div><div class="work-body"><div class="work-title-row"><span class="work-mini-icon">'+esc(String(p.title||'作品').slice(0,1))+'</span><h3>'+esc(p.title)+'</h3></div><div class="work-author">'+esc(shared?'@'+(p.author?.name||'创作者'):date(p.updatedAt))+'</div><p>'+esc(p.summary||'还没有填写介绍。')+'</p><div class="tags">'+(shared?'<span class="tag">'+esc(p.status||'进行中')+'</span>':tag(p))+'</div></div></a></article>';}
function workRow(p){return '<article class="work-list-card"><a href="#project/'+encodeURIComponent(p.id)+'"><span class="work-list-icon">'+icon('folder',23)+'</span><div class="work-list-info"><h3>'+esc(p.title)+'</h3><p>'+esc(p.summary||'还没有填写介绍。')+'</p><div class="tags"><span class="tag">'+esc(p.status||'进行中')+'</span>'+(p.tech?'<span class="muted small-text">'+esc(p.tech)+'</span>':'')+'</div></div><div class="work-list-meta">'+tag(p)+'<small>'+date(p.updatedAt)+'</small></div></a></article>';}
function profileOverview(){const p=personal(),list=works(),signed=state.user||state.local;return '<section class="profile-overview"><div class="profile-identity"><span class="avatar large">'+esc((p.name||'我').slice(0,1))+'</span><div><div class="profile-name-row"><h1>'+esc(p.name||'我的个人空间')+'</h1><span class="tag">'+(state.user?'创作者':state.local?'本机试用':'尚未登录')+'</span></div><p>'+esc(p.bio||(signed?'写下正在做的事和擅长的技能，让自己的档案更完整。':'登录后，在这里整理作品、文件和参赛经历。'))+'</p><div class="tags">'+(p.skills?String(Array.isArray(p.skills)?p.skills.join('、'):p.skills).split(/[,，、]/).filter(Boolean).slice(0,4).map(t=>'<span class="tag">'+esc(t)+'</span>').join(''):'')+'</div></div></div><div class="profile-actions"><a class="btn small" href="#'+(signed?'profile':'login')+'">'+(signed?'编辑资料':'登录账号')+'</a>'+btn('导出我的资料','export-menu','small')+'</div><div class="profile-stats"><a href="#archive/works"><strong>'+list.length+'</strong><span>作品</span></a><a href="#archive/files"><strong>'+state.files.length+'</strong><span>文件</span></a><a href="#my-posts"><strong>'+state.posts.length+'</strong><span>帖子</span></a></div><p class="profile-privacy-note">'+icon('lock',14)+' 私人资料只在这里整理；你主动提交的内容审核通过后才会公开。</p></section>';}

function filesView(list){return list.length?`<div class="file-list">${list.map(f=>`<div class="file-row"><span class="file-type">${esc(f.name.split('.').pop().toUpperCase().slice(0,4))}</span><div class="file-info"><strong>${esc(f.name)}</strong><small>${bytes(f.size)} · ${esc(f.category)} · ${date(f.createdAt)}</small></div><div class="action-row"><a class="text-button" href="api/files/${encodeURIComponent(f.id)}/download" download>下载</a><button class="text-button" data-action="delete-file" data-id="${esc(f.id)}">删除</button></div></div>`).join('')}</div>`:empty('把作品资料放在一起','先上传一张截图或一份说明，之后可以按作品找到它。',btn('上传第一份文件','upload','primary'),'file');}
function archive(sub=''){const list=works();let body='';const notice=state.local&&!state.user?'<div class="notice info">当前为本机试用，资料只在这个浏览器。<a href="#login"><strong>登录后可导入 →</strong></a></div>':!state.user&&legacy.works.length?'<div class="notice">找到 '+legacy.works.length+' 件旧浏览器作品，仍保留在本机。'+btn('继续整理','local','small')+' <a href="#login">登录后导入</a></div>':'';
if(!sub)body='<div class="section-heading"><h2>我的作品</h2>'+btn('添加作品','new-work','small primary')+'</div><div class="work-list">'+(list.length?list.map(workRow).join(''):empty('还没有保存作品','添加作品介绍、链接和个人贡献，保存后可以选择是否公开。',btn('添加第一件作品','new-work','primary'),'folder'))+'</div>';
else if(sub==='works')body='<div class="search-row"><label class="search-box">'+icon('search',18)+'<input id="work-search" placeholder="搜索作品、介绍或技能" aria-label="搜索我的作品"></label><select id="work-filter" class="filter-select" aria-label="作品状态"><option value="">全部状态</option><option>灵感阶段</option><option>进行中</option><option>已完成</option></select>'+btn('＋ 新建','new-work','small primary')+'</div><div class="work-list" id="work-results">'+(list.length?list.map(workRow).join(''):empty('还没有保存作品','先添加作品，之后可以在这里查找和继续修改。',btn('添加作品','new-work','primary'),'folder'))+'</div>';
else if(sub==='files')body='<div class="section-heading"><h2>资料文件</h2>'+btn('＋ 上传文件','upload','small primary')+'</div><div class="notice">支持图片、PDF、文字笔记，单个最多 10 MB。视频和代码可保存链接；链接不会自动备份内容。</div>'+filesView(state.files);
else body='<div class="section-heading"><h2>更新记录</h2><span class="small-text muted">打开作品可查看历史版本</span></div>'+(list.length?'<div class="card timeline">'+[...list].sort((a,b)=>(b.updatedAt||0)-(a.updatedAt||0)).map(p=>'<div class="timeline-item"><small>'+date(p.updatedAt)+'</small><p><a href="#project/'+p.id+'"><strong>'+esc(p.title)+'</strong></a></p><span class="small-text muted">'+esc(p.status||'进行中')+' · '+(p.id.startsWith('local-')?'本机保存，无历史版本':'已保存当前版本')+'</span></div>').join('')+'</div>':empty('还没有更新记录','保存作品后，每次修改会留下一份文字版本。',btn('添加作品','new-work','primary'),'clock'));
return '<div class="page-layout"><div class="main-column personal-content">'+profileOverview()+myTabs(sub)+notice+body+'</div>'+personalAside()+'</div>';}
function personalAside(){return '<aside class="aside-column personal-aside"><section class="card tight"><div class="storage-head"><h3>我的资料空间</h3>'+icon('folder',18)+'</div><div class="storage-bar"><span style="width:'+Math.min(100,state.usage.used/state.usage.limit*100)+'%"></span></div><p class="small-text muted">'+(state.user?bytes(state.usage.used)+' / '+bytes(state.usage.limit):'登录后可保存作品附件')+'</p><p class="small-text muted">单个文件最多 10 MB。文件始终私密。</p></section><section class="card tight"><h3>个人资源</h3><div class="side-links"><a href="#discover/bookmarks">'+icon('bookmark',16)+' 我的收藏 →</a><a href="#notifications">'+icon('bell',16)+' 消息通知 →</a><button data-action="export-menu">'+icon('download',16)+' 导出我的资料 →</button></div></section><section class="card tight"><h3>参赛工具</h3><div class="side-links"><a href="#prepare">生成参赛建议 →</a><a href="#credential">制作凭证草稿 →</a></div><p class="small-text muted">建议使用本地规则；凭证草稿未签名、未上链。</p></section><div class="side-links personal-settings"><a href="#profile">个人资料与账号设置 →</a><a href="#privacy">隐私与使用说明 →</a></div></aside>';}


function postCard(p,own=false){const raw=String(p.body||''),lines=raw.split('\n'),lead=lines.shift()||'',rest=lines.join('\n'),long=raw.length>280,open=expandedPosts.has(p.id),associated=state.feed.projects.find(w=>w.id===p.projectId),author=esc(p.author?.name||personal().name||'我'),profileLink=p.author?.id?(own?'#profile':'#public/'+encodeURIComponent(p.author.id)):'',authorUI=profileLink?`<a class="post-author" href="${profileLink}">${author}</a>`:`<strong>${author}</strong>`;return `<article class="card post-card" data-post-id="${esc(p.id)}"><div class="post-meta"><span class="avatar">${esc((p.author?.name||'我').slice(0,1))}</span><div>${authorUI}<small>${date(p.createdAt)} · ${{update:'作品进展',question:'提问交流',team:'寻找伙伴'}[p.kind]||'动态'}</small></div>${own?`<span class="tag amber push-right">${{pending:'待审核',approved:'已公开',rejected:'未通过审核'}[p.review]||'待审核'}</span>`:''}</div><div class="post-content ${long&&!open?'is-collapsed':''}"><p class="post-lead">${esc(lead)}</p>${rest?`<p class="post-rest">${esc(rest)}</p>`:''}</div>${long?`<button class="text-button post-expand" data-action="toggle-post" data-id="${esc(p.id)}" aria-expanded="${open}">${open?'收起内容':'展开全文'}</button>`:''}${associated?`<a class="post-project-link" href="#shared/${encodeURIComponent(associated.id)}">${icon('folder',16)} 查看关联作品：${esc(associated.title)} ${icon('arrow',16)}</a>`:''}<div class="post-actions">${own?`<button data-action="delete-post" data-id="${esc(p.id)}">删除这条动态</button>`:`<button data-action="post-comments" data-id="${esc(p.id)}">${icon('chat',17)} 回复 ${Number(p.comments)||0}</button><button class="${p.liked?'active':''}" data-action="like" data-id="${esc(p.id)}" aria-label="点赞，${p.likes||0}个赞" aria-pressed="${!!p.liked}">${icon('heart',17)} ${p.likes||0}</button><button class="${p.bookmarked?'active':''}" data-action="bookmark" data-id="${esc(p.id)}" aria-pressed="${!!p.bookmarked}">${icon('bookmark',17)} ${p.bookmarked?'已收藏':'收藏'}</button>${p.author?.id&&p.author.id!==state.user?.id?`<button data-action="start-chat" data-id="${esc(p.author.id)}" data-name="${author}">${icon('chat',17)} 私聊</button>`:''}`}</div></article>`;}
function personalEvents(){const records=works().filter(p=>p.event);return `<div class="page-layout"><div class="main-column personal-content">${profileOverview()}${myTabs('events')}<div class="section-heading"><h2>我的参赛资料</h2><span class="small-text muted">准备材料，整理经历</span></div><div class="tool-grid"><section class="card tool-card"><span class="quick-icon">${icon('compass',25)}</span><div><h3>参赛准备建议</h3><p class="muted">填写兴趣和技能，粘贴赛事要求，得到准备方向与提交清单。</p><a class="btn small primary" href="#prepare">开始准备 →</a></div></section><section class="card tool-card"><span class="quick-icon">${icon('trophy',25)}</span><div><h3>凭证草稿</h3><p class="muted">整理活动名、签发方和参与说明，生成待确认的凭证文件。</p><a class="btn small" href="#credential">制作草稿 →</a></div></section></div><section><div class="section-heading"><h2>我记录的参赛作品</h2><span class="tag">本人填写</span></div>${records.length?`<div class="work-grid">${records.map((p,i)=>workCard(p,i)).join('')}</div>`:empty('把参赛作品收进档案','添加作品时填写比赛名称，就能在这里一起查看。',btn('添加参赛作品','new-work','primary'),'trophy')}</section><div class="notice">目前没有接入主办方名单。本人填写的经历不代表官方认证；凭证草稿未签名、未上链。</div></div><aside class="aside-column"><section class="card"><h3>比赛方确认，下一步接入</h3><p class="profile-blurb">确认谁参加过、谁获了奖，需要主办方核对原始记录。现在不会根据自己填写的名字自动发认证。</p><span class="tag">尚未开放赛事管理</span></section><section class="card soft"><h3>已经有作品了？</h3><p class="profile-blurb">保存链接、补充个人贡献，再导出展示页用于演示。</p>${btn('导出作品展示页','export-html','wide')}</section></aside></div>`;}

const directories=[
 {name:'Colosseum',label:'区块链 · 黑客松',intro:'查看 Colosseum 发布的黑客松、规则与提交入口。',url:'https://colosseum.com/',symbol:'C'},
 {name:'Devpost',label:'综合 · 黑客松',intro:'浏览线上与线下黑客松，按自己的方向寻找比赛。',url:'https://devpost.com/hackathons',symbol:'D'},
 {name:'Devfolio',label:'开发者 · 黑客松',intro:'查看开发者活动、黑客松介绍及报名信息。',url:'https://devfolio.co/hackathons',symbol:'V'}
];
async function loadFeed(){try{state.feed=await api('/feed');return '';}catch{state.feed={projects:[],posts:[]};return '<div class="notice warning">公开内容加载失败，<button class="text-button" data-action="reload">重新加载</button></div>';}}
function publicAside(showWeekly=true){
 const featured=showWeekly?'<section class="card tight"><div class="section-heading"><h3>本周优秀创作者</h3>'+icon('trophy',18)+'</div><div class="aside-empty"><span class="tag">名单待发布</span><p>评选规则确定后，展示本周推荐的创作者。</p></div><a class="btn small wide" href="#creators">查看创作者 →</a></section>':'';
 return '<aside class="aside-column">'+featured+'<section class="card tight"><h3>创作交流</h3><div class="side-links"><a href="#home/update">分享作品进展 →</a><a href="#home/question">看看大家的问题 →</a><a href="#home/team">寻找一起创作的伙伴 →</a></div>'+btn('写一条动态','new-post','small primary wide')+'</section><section class="card tight"><h3>比赛入口</h3><div class="side-links">'+directories.map(d=>'<a href="'+d.url+'" target="_blank" rel="noopener noreferrer"><span>'+d.name+'<small class="muted"> · 官网</small></span>↗</a>').join('')+'</div><a class="btn small wide" href="#events">查看全部 →</a></section><p class="side-note">作品和动态通过审核后才会公开。推荐名单不代表官方能力认证。</p></aside>';
}

function weekly(){return '<section class="weekly-strip"><div class="weekly-symbol">'+icon('trophy',28)+'</div><div class="section-heading"><h2>本周优秀创作者</h2><span class="tag">名单待发布</span></div></section>'; }
function publicAuthors(){return [...new Map([...state.feed.projects,...state.feed.posts].filter(p=>p.author).map(p=>[p.author.id,p.author])).values()];}
function creatorCard(a){const ps=state.feed.projects.filter(p=>p.author?.id===a.id),posted=state.feed.posts.filter(p=>p.author?.id===a.id),skills=[...new Set(ps.flatMap(p=>(p.tech||'').split(/[,，、]/)).filter(Boolean))].slice(0,3);return '<article class="card creator-card"><a href="#public/'+encodeURIComponent(a.id)+'"><div class="profile-top"><span class="avatar large">'+esc(String(a.name||'创作者').slice(0,1))+'</span><div><h3>'+esc(a.name)+'</h3><small class="muted">'+ps.length+' 件公开作品 · '+posted.length+' 条帖子</small></div></div><div class="tags">'+skills.map(s=>'<span class="tag">'+esc(s)+'</span>').join('')+'</div><p>'+esc(ps[0]?.role||'从作品了解这位创作者的实践经历。')+'</p></a><div class="creator-card-actions"><a class="text-button" href="#public/'+encodeURIComponent(a.id)+'">查看作品与经历 →</a>'+(a.id!==state.user?.id?'<button class="text-button" data-action="start-chat" data-id="'+esc(a.id)+'" data-name="'+esc(a.name)+'">'+icon('chat',16)+' 私聊</button>':'')+'</div></article>';}
async function creators(){const warning=await loadFeed(),authors=publicAuthors(),examples=demoUI('creatorCards');return heading('创作者','','<a class="btn small" href="#profile">完善我的介绍</a>')+weekly()+'<div class="page-layout"><div class="main-column">'+warning+'<div class="section-heading"><h2>全部创作者</h2></div><label class="search-box">'+icon('search',18)+'<input id="creator-search" aria-label="搜索创作者" placeholder="搜索昵称、作品或技能"></label><div class="creator-grid" id="creator-results">'+(authors.map(creatorCard).join('')+examples||empty('还没有公开创作者','作品或帖子审核公开后，你会出现在这里。','<a class="btn primary" href="#archive/works">整理我的作品</a>','person'))+'</div></div>'+publicAside(false)+'</div>';}
function communityAside(){return '<aside class="aside-column community-aside"><section class="card tight"><h3>我的交流</h3><div class="side-links"><a href="#my-posts">'+icon('chat',18)+' 我的帖子</a><a href="#notifications">'+icon('bell',18)+' 消息通知</a><a href="#archive">'+icon('folder',18)+' 我的档案</a></div></section><section class="card tight"><h3>常用入口</h3><div class="side-links"><a href="#discover/bookmarks">'+icon('bookmark',18)+' 我的收藏</a><a href="#prepare">'+icon('compass',18)+' 参赛准备</a><a href="#events">'+icon('trophy',18)+' 查看比赛</a></div></section></aside>'; }
function homeScene(){return `<header class="home-scene"><div class="home-scene-copy"><span class="home-scene-label">创作者社区</span><h1>首页</h1><p>分享作品进展 · 交流问题 · 寻找伙伴</p></div><svg class="home-scene-art" viewBox="0 0 390 190" fill="none" aria-hidden="true"><defs><linearGradient id="home-sheet" x1="92" y1="36" x2="290" y2="178" gradientUnits="userSpaceOnUse"><stop stop-color="white" stop-opacity=".92"/><stop offset="1" stop-color="white" stop-opacity=".16"/></linearGradient><linearGradient id="home-leaf" x1="164" y1="126" x2="246" y2="38" gradientUnits="userSpaceOnUse"><stop stop-color="#39c9b1"/><stop offset="1" stop-color="#c0e966"/></linearGradient><linearGradient id="home-edge" x1="102" y1="47" x2="313" y2="169" gradientUnits="userSpaceOnUse"><stop stop-color="white"/><stop offset="1" stop-color="#38bca3" stop-opacity="0"/></linearGradient></defs><path d="M16 132 184 33l164 95-166 57Z" stroke="#26b89b" stroke-opacity=".2"/><path d="m50 147 165-98 137 79M183 184V33" stroke="#26b89b" stroke-opacity=".15"/><path d="m150 17 181 32 13 18-24 110-190-34Z" fill="#41cbb4" fill-opacity=".12" stroke="#fff" stroke-opacity=".7"/><path d="m107 37 194 18 12 15-12 103-206-19Z" fill="url(#home-sheet)" stroke="url(#home-edge)"/><path d="m78 64 189-2 17 17v86H78Z" fill="url(#home-sheet)" stroke="url(#home-edge)"/><path d="M95 86h45M95 94h29" stroke="#24a88b" stroke-opacity=".48" stroke-width="3"/><path d="M98 149h30m9 0h20m13 0h30" stroke="#26b89b" stroke-opacity=".22" stroke-width="3"/><path d="M182 139c-2-31 17-60 45-76" stroke="#1da78d" stroke-width="2"/><path d="M198 109c-6-25 2-51 41-59-1 37-12 55-41 59Z" fill="url(#home-leaf)"/><path d="M185 127c-24 4-45-6-53-29 33-7 48 2 53 29Z" fill="url(#home-leaf)" fill-opacity=".82"/><path d="m199 108 29-40m-43 59-37-19" stroke="white" stroke-opacity=".7"/><circle cx="323" cy="103" r="20" fill="white" fill-opacity=".24" stroke="white" stroke-opacity=".7"/><path d="m318 103 4 4 8-9" stroke="#159878" stroke-width="2"/><path d="M52 54h12m-6-6v12" stroke="#2bb99c" stroke-opacity=".45"/><circle cx="303" cy="28" r="3" fill="#b4df56"/></svg></header>`;}
function communityStarter(kind,warning){const ideas=[{kind:'update',symbol:'folder',title:'作品进展',desc:'说清做了什么、做到哪一步，可以关联自己的作品。',sample:'今天完成了作品上传，下一步准备做个人主页。'},{kind:'question',symbol:'chat',title:'提问交流',desc:'写具体问题和试过的方法，别人更容易给出建议。',sample:'我想验证参赛记录，除了获奖截图，还应该保留什么？'},{kind:'team',symbol:'person',title:'寻找伙伴',desc:'介绍正在做的事、你负责什么、想找哪种伙伴。',sample:'我负责产品和页面，想找懂区块链的伙伴一起做比赛作品。'}],selected=kind?ideas.filter(x=>x.kind===kind):ideas;return '<section class="community-empty" aria-labelledby="community-start-title"><div class="starter-intro"><span class="starter-kicker">'+(warning?'公开内容暂未加载':kind?'这个分类还没有公开帖子':'这里还没有公开帖子')+'</span><h2 id="community-start-title">写一条具体的内容，开始交流</h2><p>先说清正在做的事、遇到的问题，或想找的伙伴。下面是写法示例，不是真实帖子。</p></div><div class="starter-grid '+(kind?'single-starter':'')+'">'+selected.map(x=>'<article class="starter-card"><span class="starter-mark">'+icon(x.symbol,25)+'</span><h3>'+x.title+'</h3><p>'+x.desc+'</p><div class="starter-example"><span>写法示例</span><p>'+esc(x.sample)+'</p></div></article>').join('')+'</div><div class="starter-foot"><div><strong>写好后提交，审核通过再公开</strong><p>提交后可到“我发的帖子”查看状态；未通过的内容不会公开。</p></div>'+btn('写一条帖子','new-post','primary')+'</div><div class="community-empty-tools"><span>也可以先</span><a href="#archive/works">整理自己的作品 '+icon('arrow',15)+'</a><a href="#events">查看比赛与准备工具 '+icon('arrow',15)+'</a></div></section>';}
async function community(sub=''){
 const warning=await loadFeed(),kind=['update','question','team'].includes(sub)?sub:'',focusId=new URLSearchParams(state.route.split('?')[1]||'').get('post');let focusError='';
 if(focusId&&!state.feed.posts.some(p=>p.id===focusId)){try{const d=await api('/comments?postId='+encodeURIComponent(focusId));if(d.post)state.feed.posts.push(d.post);}catch(e){focusError=e.message;}}
 const posts=state.feed.posts.filter(p=>focusId?p.id===focusId:!kind||p.kind===kind),examples=focusId?'':demoUI('postCards',kind),feedContent=posts.length||examples?'<div class="feed-post-list">'+posts.map(p=>postCard(p)).join('')+examples+'</div>':focusId?empty('原帖子暂时无法查看',esc(focusError||'内容可能已删除或不再公开。'),'<a class="btn" href="#home">返回全部帖子</a>','chat'):communityStarter(kind,warning);
 return homeScene()+'<div class="page-layout community-page"><div class="main-column community-main">'+warning+'<section class="community-feed" aria-label="社区帖子"><button class="compose-entry" data-action="new-post"><span class="avatar">'+esc((personal().name||'我').slice(0,1))+'</span><span class="compose-entry-copy"><strong>分享你的新进展…</strong></span><span class="compose-button">发帖子 '+icon('plus',16)+'</span></button><div class="feed-toolbar">'+(focusId?'<a class="text-button" href="#home">← 返回全部帖子</a>':tabs('home',[['','全部'],['update','作品进展'],['question','提问交流'],['team','寻找伙伴']],kind))+'</div>'+feedContent+'</section></div>'+communityAside()+'</div>';
}
async function searchPage(){const q=new URLSearchParams(state.route.split('?')[1]||'').get('q')?.trim()||'',warning=await loadFeed();if(!q)return heading('搜索社区','输入作品名、创作者昵称或想了解的话题。')+empty('先输入一个关键词','在顶部搜索框输入内容，按回车搜索。','','search');const demoResults=demoUI('search',q),needle=q.toLowerCase(),ps=state.feed.projects.filter(p=>[p.title,p.summary,p.tech,p.author?.name].join(' ').toLowerCase().includes(needle)),posts=state.feed.posts.filter(p=>[p.body,p.author?.name].join(' ').toLowerCase().includes(needle)),authors=publicAuthors().filter(a=>[...state.feed.projects,...state.feed.posts].some(p=>p.author?.id===a.id&&[a.name,p.tech,p.role,p.body].join(' ').toLowerCase().includes(needle)));return heading('搜索结果','关键词：'+esc(q)+' · 公开内容与标注的演示样例')+'<div class="page-layout"><div class="main-column search-results">'+warning+(ps.length||posts.length||authors.length||demoResults?(ps.length?'<section><div class="section-heading"><h2>作品</h2></div><div class="work-grid">'+ps.map((p,i)=>workCard(p,i,true)).join('')+'</div></section>':'')+(authors.length?'<section><div class="section-heading"><h2>创作者</h2></div><div class="creator-grid">'+authors.map(creatorCard).join('')+'</div></section>':'')+(posts.length?'<section><div class="section-heading"><h2>动态</h2></div>'+posts.map(p=>postCard(p)).join('')+'</section>':'')+demoResults:empty('没有找到相关内容','换一个关键词试试看。私人资料不会出现在社区搜索里。','','search'))+'</div>'+publicAside()+'</div>';}

async function discover(sub=''){const warning=await loadFeed();if(sub==='bookmarks')return heading('我的收藏','收藏过的社区动态，集中在这里。')+myTabs('bookmarks')+warning+(state.feed.posts.some(p=>p.bookmarked)?state.feed.posts.filter(p=>p.bookmarked).map(p=>postCard(p)).join(''):empty('还没有收藏的动态','在社区动态下面点“收藏”，以后就能在这里找到。','<a class="btn" href="#home">去社区看看</a>','bookmark'));const examples=demoUI('projectCards');return heading('作品','',btn('添加我的作品','new-work','small primary'))+'<div class="page-layout"><div class="main-column">'+warning+'<div class="search-row"><label class="search-box">'+icon('search',18)+'<input id="discover-search" aria-label="搜索公开作品" placeholder="搜索作品、技能或创作者"></label></div><div class="work-grid" id="discover-results">'+(state.feed.projects.map((p,i)=>workCard(p,i,true)).join('')+examples||empty('还没有公开作品','先保存作品，准备好再提交公开。',btn('添加我的作品','new-work','primary'),'folder'))+'</div></div>'+publicAside(false)+'</div>'; }
function events(){const examples=demoUI('eventCards');return heading('比赛','','<a class="btn small" href="#archive/events">我的参赛资料 →</a>')+'<div class="page-layout"><div class="main-column">'+(examples?'<div class="section-heading"><h2>脑洞挑战</h2><span class="demo-badge">演示活动</span></div><div class="demo-event-grid">'+examples+'</div>':'')+'<section class="event-directories"><div class="section-heading"><h2>真实赛事平台</h2></div><div class="directory-links">'+directories.map(d=>'<a href="'+d.url+'" target="_blank" rel="noopener noreferrer"><strong>'+d.name+'</strong><span>'+d.label+'</span><b aria-hidden="true">↗</b></a>').join('')+'</div><p class="small-text muted">日期、参赛资格与报名以官网为准。</p></section></div><aside class="aside-column"><section class="card tight"><h3>参赛工具</h3><a class="btn primary wide" href="#prepare">生成参赛建议</a></section><section class="card tight"><h3>我的参赛资料</h3><div class="side-links"><a href="#archive/events">作品与参赛经历 →</a><a href="#archive/files">截图、文档与材料 →</a><a href="#credential">制作凭证草稿 →</a></div></section><p class="side-note">演示活动不提供报名；主办方认证尚未开放。</p></aside></div>'; }
function myTabs(active='works'){return tabs('archive',[['works','作品'],['files','资料文件'],['events','参赛经历'],['posts','我的动态'],['notifications','消息通知']],!active||active==='history'?'works':active).replace('class="subtabs"','class="subtabs my-tabs"');}

const field=(label,name,value='',opts={})=>`<label class="field ${opts.full?'full':''}">${label}${opts.area?`<textarea name="${name}" maxlength="${opts.max||3000}" ${opts.required?'required':''}>${esc(value)}</textarea>`:`<input name="${name}" value="${esc(value)}" maxlength="${opts.max||300}" ${opts.required?'required':''} ${opts.type?`type="${opts.type}"`:''}>`}${opts.help?`<small>${opts.help}</small>`:''}</label>`;
function profile(){if(!state.user&&!state.local)return login();const p=personal();return `<div class="page-narrow">${heading('个人中心','写清你擅长什么、在做什么。')}${myTabs('profile')}<form id="profile-form" class="card"><div class="profile-top"><span class="avatar large">${esc((p.name||'我').slice(0,1))}</span><div><h2>编辑个人档案</h2><span class="tag green">创作者</span></div></div><div class="form-grid">${field('昵称','name',p.name,{required:true,max:40})}${field('擅长的技能','skills',p.skills)}${field('介绍自己与过往经历（先私密保存）','bio',p.bio,{area:true,full:true,max:600})}${field('想找什么样的伙伴','intent',p.intent,{full:true,max:200})}</div><div class="notice info" style="margin-top:22px">公开作品页只展示昵称及审核通过的作品。简介和找伙伴意向先保存在私人档案，不公开手机号、真实姓名和学校。</div><p class="form-error" role="alert"></p><div class="form-footer"><a class="btn" href="#archive">返回我的</a><button class="btn primary" type="submit">保存个人档案</button></div></form><section class="card" style="margin-top:22px"><h2>账号与资料</h2><div class="side-links"><button data-action="export-data">导出文字记录与文件清单 ${icon('download',17)}</button><a href="#privacy">隐私与使用说明 ${icon('arrow',17)}</a>${state.user?'<button data-action="logout">退出当前账号 →</button>':'<a href="#login">登录并开启服务器保存 →</a>'}</div><p class="small-text muted">${state.user?'账号：'+esc(state.user.username)+'。手机号登录和自助找回密码暂未开放，请保存好密码。':'当前为本机试用，没有账号同步。'}</p></section></div>`;}
function login(register=false){return `<section class="auth-layout"><div class="auth-visual"><h1>你的下一件作品，<br>从这里开始记录。</h1><p>登录后，作品与文件保存在服务器。换一台电脑，也能接着整理。</p>${art}</div><div class="auth-form">${tabs('login',[['','登录账号'],['register','创建账号']],register?'register':'')}<form id="auth-form" data-register="${register}">${register?'<label class="field">昵称<input name="name" required maxlength="40" autocomplete="nickname" placeholder="你希望大家怎么称呼你"></label>':''}<label class="field">账号<input name="username" required pattern="[A-Za-z0-9_]{3,32}" maxlength="32" autocomplete="username" placeholder="3–32 位字母、数字或下划线"></label><label class="field">密码<input name="password" type="password" required minlength="10" maxlength="128" autocomplete="${register?'new-password':'current-password'}" placeholder="至少 10 位，请妥善保存"></label>${register?'<p class="small-text muted">目前没有自助找回密码，请保存好密码。无需填写手机号和真实姓名。</p><label class="check-label"><input type="checkbox" required><span>我已阅读<a href="#privacy" target="_blank">隐私与使用说明</a>，明白新资料默认私密。</span></label>':''}<p class="form-error" role="alert"></p><button type="submit" class="btn primary wide" ${state.ready?'':'disabled'}>${register?'创建账号':'登录并继续'}</button></form><button class="text-button" data-action="local">先在当前浏览器试用 →</button><div class="notice info"><strong>手机号登录暂未接通</strong><p>短信服务需要网站方配置。现在使用账号密码登录，不会发送验证码。</p></div></div></section>`;}
function privacy(){return `<div class="page-narrow">${heading('隐私与使用说明','先知道资料放在哪里，再决定是否上传。')}<div class="card privacy-list"><section><h3>保存什么</h3><p>账号、昵称、作品介绍、你上传的附件、帖子、回复及私人对话。不要填写真实住址、学校、身份证号和私人联系方式。密码经过单向处理保存，不保存明文密码。</p></section><section><h3>谁能看见</h3><p>档案与附件默认私密，登录本人账号才能查看。选择提交公开的作品和动态由运营审核后展示；运营处理审核和维护时可能接触相关资料。附件始终私密。私聊仅双方账号可查看，不会出现在公开搜索里；私聊没有端到端加密，网站运营维护时可能接触记录。</p></section><section><h3>怎么撤回和带走</h3><p>作品改回私密后，会从发现页撤下。可以删除作品、动态、文件；文件删除无法恢复。可以导出文字记录，附件需单独下载。备份记录的清理需要网站运营方处理。</p></section><section><h3>当前限制</h3><p>本机试用只保存在当前浏览器。登录后保存的内容才进入服务器。尚未启用自动定期备份、自助找回密码、手机号登录、账号注销入口和主办方认证。重要资料请另存一份，体验阶段请使用非敏感内容。</p></section><section><h3>公开记录不代表认证</h3><p>内容审核、本人填写的经历、组织者确认是三回事。凭证目前只是未签名、未上链的草稿，不能证明原创或获奖。</p></section><a href="#archive" class="btn primary">回到我的</a></div></div>`;}
async function project(id,shared=false){const p=(shared?state.feed.projects:works()).find(p=>p.id===id);if(!p)return empty('没有找到这件作品','可能已被删除、改为私密，或需要登录本人账号。','<a class="btn" href="#archive/works">返回作品列表</a>');let versions=[];if(state.user&&!shared){try{versions=(await api(`/projects/${id}/history`)).versions;}catch{}}const url=safeURL(p.url);return `${heading(shared?'作品详情':'作品档案',shared?'创作者主动公开的作品资料。':'基本介绍、相关文件与修改记录。',shared?'':btn('编辑作品','edit-work','small primary',id))}<section class="detail-cover"><span class="cover-symbol" aria-hidden="true">✳</span><div><div class="tags">${shared?'<span class="tag green">公开作品</span>':tag(p)}<span class="tag">${esc(p.status)}</span></div><h1>${esc(p.title)}</h1><p>${esc(p.summary)}</p></div></section><div class="page-layout"><div class="main-column"><section class="card"><h2>作品介绍</h2><dl class="detail-grid"><div><dt>用到的工具与技能</dt><dd>${esc(p.tech||'还没有填写')}</dd></div><div><dt>我负责的部分</dt><dd>${esc(p.role||'还没有填写')}</dd></div>${!shared?`<div><dt>参赛经历（本人填写）</dt><dd>${esc(p.event||'还没有填写')}</dd></div>`:''}<div><dt>作品链接</dt><dd>${url?`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">打开作品 ↗</a>`:'还没有填写'}</dd></div></dl>${!shared?`<h3>制作笔记</h3><p class="pre-wrap muted">${esc(p.notes||'下次编辑时，可以记下遇到的问题和新的进展。')}</p>`:''}</section>${!shared?`<section><div class="section-heading"><h2>这件作品的文件</h2>${btn('关联新文件','upload','small',id)}</div>${filesView(state.files.filter(f=>f.projectId===id))}</section><section class="card"><h2>历史文字版本</h2><p class="small-text muted">最多保存最近 30 个文字版本，不是区块链存证。</p>${versions.length?versions.map(v=>`<details><summary>${date(v.createdAt)} · ${esc(v.title)}</summary><p class="pre-wrap small-text">${esc(v.summary)}${v.notes?'\n'+esc(v.notes):''}</p></details>`).join(''):'<p class="muted">还没有之前的版本。</p>'}</section>`:''}</div><aside class="aside-column"><section class="card"><h3>${shared?'关于创作者':'可见范围'}</h3><p class="profile-blurb">${shared?esc(p.author?.name||'创作者'):p.visibility==='public'?'已申请公开。审核通过后展示作品介绍，不公开附件、私人笔记和自行填写的参赛经历。':'只有你登录后能查看。想展示作品，可以编辑后选择“提交公开”。'}</p>${shared&&p.author?`<a class="btn wide" href="#public/${encodeURIComponent(p.author.id)}">查看创作者作品</a>${p.author.id!==state.user?.id?`<button class="btn wide small" data-action="start-chat" data-id="${esc(p.author.id)}" data-name="${esc(p.author.name)}">${icon('chat',17)} 私聊</button>`:''}`:shared?'':btn('编辑内容与可见范围','edit-work','wide',id)}</section>${!shared?`<section class="card tight"><h3>整理操作</h3><div class="side-links"><button data-action="export-html">导出我的作品页</button><button data-action="delete-work" data-id="${id}">删除这份作品档案</button></div><p class="small-text muted">删除作品后，文件仍会留在资料库。</p></section>`:''}</aside></div>`;}
function notificationItems(){return [...state.projects.filter(p=>p.visibility==='public').map(p=>({title:p.title,review:p.review,route:`project/${p.id}`,kind:'作品'})),...state.posts.map(p=>({title:p.body.slice(0,70),review:p.review,route:'my-posts',kind:'帖子'}))];}
function activityNotice(item){const liked=item.kind==='like',route=item.targetKind==='project'?'shared/'+encodeURIComponent(item.targetId):'home?post='+encodeURIComponent(item.targetId),name=esc(item.actor?.name||'创作者');return `<a class="notification-item ${item.read?'':'unread'}" href="#${route}" data-action="open-notification" data-id="${esc(item.id)}" data-route="${esc(route)}"><span class="notification-icon">${icon(liked?'heart':'chat',22)}</span><div class="notification-copy"><div class="notification-meta"><strong>${name}${liked?'赞了你的'+(item.targetKind==='project'?'作品':'帖子'):'回复了你的帖子'}</strong><small>${date(item.createdAt)}</small>${item.read?'':'<span class="notification-dot" aria-label="未读"></span>'}</div><p class="notification-target">${esc(item.title||'查看原内容')}</p>${!liked&&item.body?'<p class="notification-excerpt">'+esc(item.body)+'</p>':''}<span class="notification-open">${liked?'查看原内容':'查看帖子与回复'} →</span></div></a>`;}
function reviewNotice(item){return `<a class="notification-item review-item" href="#${item.route}"><span class="notification-icon">${icon('bell',22)}</span><div class="notification-copy"><div class="notification-meta"><strong>${item.kind}审核状态</strong><span class="tag ${item.review==='approved'?'green':''}">${{pending:'待审核',approved:'已公开',rejected:'未通过'}[item.review]||'等待处理'}</span></div><p class="notification-target">${esc(item.title)}</p><p class="notification-excerpt">${{pending:'已收到提交，等待人工审核。',approved:'审核通过，已出现在公开页面。',rejected:'未通过审核，可以查看原内容。'}[item.review]||'等待处理'}</p></div>${icon('arrow',16)}</a>`;}
async function notifications(sub='',seq=state.seq){const filter=['likes','replies','reviews'].includes(sub)?sub:'',owner=state.user?.id;if(notificationState.owner!==owner)Object.assign(notificationState,{owner,items:[],unreadTotal:0,error:''});if(owner){try{const [d,p,s]=await Promise.all([api('/notifications'),api('/projects'),api('/posts')]);if(seq!==state.seq||state.user?.id!==owner)return '';state.projects=p.projects;state.posts=s.posts;notificationState.items=d.activity||d.notifications||[];notificationState.unreadTotal=d.unreadTotal||0;notificationState.error='';}catch(e){if(seq!==state.seq||state.user?.id!==owner)return '';notificationState.items=[];notificationState.unreadTotal=0;notificationState.error=e.message;}}
 const activity=notificationState.items.filter(i=>['like','reply'].includes(i.kind)),reviews=notificationItems(),shown=activity.filter(i=>!filter||i.kind===(filter==='likes'?'like':'reply'));
 let body=!owner?empty('登录后查看消息通知','这里显示别人对你的点赞、已公开的回复，以及提交内容的审核状态。','<a class="btn primary" href="#login">登录账号</a>','bell'):'';
 if(owner){const failure=notificationState.error&&filter!=='reviews'?'<div class="notice warning">互动通知暂未加载：'+esc(notificationState.error)+' '+btn('重新加载','reload','small')+'</div>':'';body=failure+(filter==='reviews'?(reviews.length?'<div class="notification-list">'+reviews.map(reviewNotice).join('')+'</div>':empty('暂时没有审核记录','提交作品或帖子后，在这里查看审核状态。','<a class="btn" href="#archive/works">查看我的作品</a>','bell')):(shown.length?'<div class="notification-list">'+shown.map(activityNotice).join('')+'</div>':notificationState.error?'':empty(filter==='likes'?'暂时没有收到新的赞':filter==='replies'?'暂时没有收到新的回复':'暂时没有新的互动通知','别人点赞你的内容，或回复审核公开后，通知会出现在这里。','','bell'))+(!filter&&reviews.length?'<section class="notification-reviews"><div class="section-heading"><h3>提交内容的审核状态</h3><a class="text-button" href="#notifications/reviews">查看全部 →</a></div><div class="notification-list">'+reviews.slice(0,3).map(reviewNotice).join('')+'</div></section>':''));}
 return '<div class="page-layout"><div class="main-column personal-content notification-page">'+heading('消息通知','查看收到的赞、公开回复和审核状态。私人聊天请打开右上角“对话”。',owner&&notificationState.unreadTotal?btn('全部标为已读','read-notifications','small'):'')+myTabs('notifications')+tabs('notifications',[['','全部'],['likes','收到的赞'],['replies','收到的回复'],['reviews','审核状态']],filter).replace('class="subtabs"','class="subtabs notification-tabs"')+body+'</div>'+personalAside()+'</div>';
}
function closeMessages(){if(!messageState.open)return;stopChatPolling();++state.seq;$('#message-panel').close();$('#message-panel-body').replaceChildren();messageState.open=false;state.route=messageState.baseRoute||'home';$('#main').setAttribute('aria-busy','false');header();nav(state.route);}
async function showMessagePanel(page,id,seq){messageState.open=true;const panel=$('#message-panel'),body=$('#message-panel-body');body.innerHTML='<div class="loading-state">正在加载对话…</div>';if(!panel.open)panel.showModal();header();try{const html=await messagesPage(id,seq,true);if(seq!==state.seq||!messageState.open||!panel.open)return;body.innerHTML=html;bindChat();}catch(e){if(seq!==state.seq)return;body.innerHTML=empty('暂时没能加载对话',esc(e.message),btn('重试','chat-retry','small primary'),'chat');}if(seq===state.seq)$('#main').setAttribute('aria-busy','false');}



function updateChatBadge(){const link=$('#message-button')||document.querySelector('[data-nav="messages"]');if(!link)return;link.querySelector('.nav-unread')?.remove();const count=state.user?chatState.unreadTotal:0;if(count)link.insertAdjacentHTML('beforeend',`<span class="nav-unread" aria-label="${count} 条未读私聊">${count>99?'99+':count}</span>`);link.title=count?`对话，${count} 条未读私聊`:'一对一私人聊天';link.setAttribute('aria-label',count?`对话，${count} 条未读私聊`:'对话：私人聊天');}
async function markNotificationsRead(ids){const owner=state.user?.id,seq=state.seq;if(!owner)return false;const d=await api('/notifications/read','POST',ids?{ids}:{all:true});if(state.user?.id!==owner||notificationState.owner!==owner||seq!==state.seq)return false;notificationState.items=notificationState.items.map(item=>!ids||ids.includes(item.id)?{...item,read:true}:item);notificationState.unreadTotal=d.unreadTotal||0;return true;}

function stopChatPolling(){clearTimeout(chatState.timer);chatState.timer=null;chatState.generation++;clearTimeout(chatState.searchTimer);chatState.searchSeq++;}
function chatRouteId(){return state.route.split('?')[0].split('/')[0]==='messages'?(state.route.split('?')[0].split('/')[1]||''):null;}
function chatTime(v){return v?new Date(typeof v==='number'?v*1000:v).toLocaleString('zh-CN',{month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit'}):'';}
function chatListHTML(){return chatState.chats.length?chatState.chats.map(c=>`<a class="chat-list-item ${chatState.current?.id===c.id?'is-active':''}" href="#messages/${encodeURIComponent(c.id)}${messageState.full?'?view=full':''}" ${chatState.current?.id===c.id?'aria-current="page"':''}><span class="avatar">${esc(String(c.peer?.name||'创作者').slice(0,1))}</span><div class="chat-peer"><div><strong>${esc(c.peer?.name||'创作者')}</strong><small>${date(c.updatedAt)}</small></div><p class="chat-preview">${esc(c.blockedByMe?'已屏蔽此人':c.preview||'打开对话')}</p>${c.state==='pending'?`<span class="tag">${c.incoming?'待接受的邀请':'等待对方接受'}</span>`:''}</div>${c.unread?`<span class="chat-unread" aria-label="${c.unread} 条未读">${c.unread>99?'99+':c.unread}</span>`:''}</a>`).join(''):'<div class="chat-empty"><h3>还没有对话</h3><p>搜索公开的创作者昵称，或者从帖子、创作者主页点“私聊”。</p></div>';}
function chatStatusHTML(c){if(c.blockedByMe)return '<div class="chat-status notice"><strong>你已屏蔽这位用户。</strong><span>对方不能再发消息。取消屏蔽后才能继续交流。</span></div>';if(c.blockedByPeer)return '<div class="chat-status notice">当前不能给对方发送消息。</div>';if(c.state==='pending')return c.incoming?'<div class="chat-status notice"><div><strong>对方发来了私聊邀请</strong><p>接受后才可以互相发消息。不想聊，可以屏蔽对方。</p></div>'+btn('接受邀请','chat-accept','small primary',c.id)+'</div>':'<div class="chat-status notice">邀请已发送，等待对方接受。接受前只能发送这一条消息。</div>';return '<div class="chat-status chat-safety-note">只向信任的人分享资料。不要发送住址、学校或密码。</div>';}
function chatMessageHTML(m){return `<div class="chat-row ${m.senderId===state.user?.id?'mine':''}" data-message-seq="${Number(m.seq)||0}"><div class="chat-bubble"><p>${esc(m.body)}</p><small class="chat-meta">${chatTime(m.createdAt)}</small></div></div>`;}
function chatMessagesHTML(){return `<div class="chat-history">${chatState.olderCursor?btn('加载更早的消息','chat-older','small'):'<span class="small-text muted">这是对话的开始</span>'}</div>`+chatState.messages.map(chatMessageHTML).join('');}
function chatCanSend(c=chatState.current){return !!c&&c.state==='accepted'&&!c.blockedByMe&&!c.blockedByPeer;}
function chatPanelHTML(){const c=chatState.current;if(!c)return '<section class="chat-panel"><div class="chat-empty">'+icon('chat',36)+'<h2>选择一段对话</h2><p>和创作者讨论进展、交流想法，或者聊聊一起做什么。</p></div></section>';const draft=chatState.drafts.get(c.id)||'';return `<section class="chat-panel" aria-label="与${esc(c.peer?.name||'创作者')}的对话"><div class="chat-panel-head"><a class="text-button chat-back" href="#messages${messageState.full?'?view=full':''}" aria-label="返回对话列表">← 返回</a><div class="chat-peer"><h2>${esc(c.peer?.name||'创作者')}</h2><small>私人对话 · 仅双方账号可见</small></div><div class="chat-panel-actions">${btn(c.blockedByMe?'取消屏蔽':'屏蔽','chat-block','small',c.id)}</div></div><div id="chat-status">${chatStatusHTML(c)}</div><div id="chat-messages" class="chat-messages" role="log" aria-live="polite" aria-relevant="additions" tabindex="0" aria-label="对话消息">${chatMessagesHTML()}</div><form id="chat-composer" class="chat-composer"><label class="sr-only" for="chat-body">消息内容</label><textarea id="chat-body" name="body" maxlength="2000" rows="3" placeholder="聊聊创作进展或组队想法…" ${chatCanSend()?'':'disabled'}>${esc(draft)}</textarea><p id="chat-error" class="chat-inline-error" role="alert"></p><div class="chat-composer-footer"><span class="chat-counter"><span id="chat-count">${draft.length}</span> / 2000</span><small>支持文字消息</small><button type="submit" class="btn primary" ${chatCanSend()&&draft.trim()?'':'disabled'}>发送</button></div></form></section>`;}
function chatShell(panel=false){if(panel)return chatPanelShell();return heading('对话','和创作者私下交流。第一次联系，先发一条邀请。')+`<div class="chat-layout ${chatState.current?'has-conversation':''}"><aside class="chat-sidebar" aria-label="对话列表"><div class="chat-search"><label class="search-box">${icon('search',18)}<input id="chat-contact-search" aria-label="搜索公开创作者昵称" maxlength="40" placeholder="搜索公开创作者昵称" autocomplete="off"></label><p class="small-text muted">仅查找已公开作品或帖子的创作者</p><div id="chat-contact-results" class="chat-contact-results" aria-live="polite"></div></div><div id="chat-list-error" class="chat-inline-error" role="alert">${esc(chatState.listError)}</div><div id="chat-list" class="chat-list">${chatListHTML()}</div></aside>${chatPanelHTML()}</div>`;}
function chatPanelShell(){const c=chatState.current,full='#messages'+(c?'/'+encodeURIComponent(c.id):'')+'?view=full';if(c)return `<div class="message-summary"><a class="text-button" href="#messages">← 会话列表</a><a class="text-button" href="${full}">展开对话 ${icon('arrow',15)}</a></div><div class="message-chat-detail">${chatPanelHTML()}</div>`;return `<div class="message-summary"><span>${chatState.chats.length?chatState.chats.length+' 段对话':'私人文字交流'}</span><a class="text-button" href="${full}">展开 ${icon('arrow',15)}</a></div><div class="message-chat-list"><div class="chat-search"><label class="search-box">${icon('search',18)}<input id="chat-contact-search" aria-label="搜索公开创作者昵称" maxlength="40" placeholder="搜索创作者昵称，发起邀请" autocomplete="off"></label><p class="small-text muted">第一次联系先发邀请，对方接受后再聊。</p><div id="chat-contact-results" class="chat-contact-results" aria-live="polite"></div></div><div id="chat-list-error" class="chat-inline-error" role="alert">${esc(chatState.listError)}</div><div id="chat-list" class="chat-list">${chatListHTML()}</div></div>`;}
async function messagesPage(id,seq,panel=false){if(!state.user){chatState.current=null;chatState.chats=[];chatState.unreadTotal=0;return (panel?'':heading('对话','私聊需要登录账号。'))+empty('登录后才能发私聊','本机试用没有账号身份，不能接收或发送私人消息。','<a class="btn primary" href="#login">登录账号</a>','chat');}const warning=[];try{const list=await api('/chats');if(seq!==state.seq)return '';chatState.chats=list.chats||[];chatState.unreadTotal=list.unreadTotal||0;chatState.listError='';}catch(e){warning.push(e.message);chatState.listError=e.message;}if(seq!==state.seq)return '';chatState.current=null;chatState.messages=[];chatState.olderCursor=null;if(id){try{const detail=await api('/chats/'+encodeURIComponent(id));if(seq!==state.seq)return '';chatState.current=detail.chat;chatState.messages=detail.messages||[];chatState.olderCursor=detail.olderCursor;await markChatRead(detail.chat.id);}catch(e){warning.push(e.message);}}if(seq!==state.seq)return '';updateChatBadge();return (warning.length?`<div class="notice warning">${esc([...new Set(warning)].join('；'))} ${btn('重新加载','chat-retry','small')}</div>`:'')+chatShell(panel);}
async function markChatRead(id){if(document.hidden||chatRouteId()!==id)return;const reader=state.user?.id;await api('/chats/'+encodeURIComponent(id)+'/read','POST',{});if(state.user?.id!==reader)return;const c=chatState.chats.find(c=>c.id===id);if(c){chatState.unreadTotal=Math.max(0,chatState.unreadTotal-(c.unread||0));c.unread=0;}if(chatState.current?.id===id)chatState.current.unread=0;updateChatBadge();}
function nearChatBottom(el){return !el||el.scrollHeight-el.scrollTop-el.clientHeight<80;}
function updateChatControls(){const c=chatState.current;if(!c||!$('#chat-composer'))return;const input=$('#chat-body'),send=$('#chat-composer [type="submit"]'),busy=chatState.sendingKeys.has(state.user?.id+'/'+c.id);input.disabled=!chatCanSend()||busy;send.disabled=!chatCanSend()||busy||!input.value.trim();send.textContent=busy?'正在发送…':'发送';$('#chat-count').textContent=input.value.length;}
function reconcileChatMessages(current,incoming,olderCursor,nextCursor){const newest=current.length?Math.max(...current.map(m=>m.seq)):0,earliest=incoming.length?Math.min(...incoming.map(m=>m.seq)):0,gap=current.length&&incoming.length&&earliest>newest+1;return {messages:[...new Map([...(gap?[]:current),...incoming].map(m=>[m.seq,m])).values()].sort((a,b)=>a.seq-b.seq),olderCursor:gap||!current.length?nextCursor:olderCursor};}
async function refreshChats(force=false){const id=chatRouteId();if(id===null||!state.user||document.hidden)return;const generation=chatState.generation;try{const list=await api('/chats');if(generation!==chatState.generation)return;chatState.chats=list.chats||[];chatState.unreadTotal=list.unreadTotal||0;chatState.listError='';if($('#chat-list'))$('#chat-list').innerHTML=chatListHTML();if($('#chat-list-error'))$('#chat-list-error').textContent='';updateChatBadge();if(!id)return;const detail=await api('/chats/'+encodeURIComponent(id));if(generation!==chatState.generation||chatRouteId()!==id)return;const previous=chatState.current;if(!previous||previous.id!==id)return;const changed=force||detail.messages.some(m=>!chatState.messages.some(old=>old.seq===m.seq)),statusChanged=JSON.stringify([previous.state,previous.blockedByMe,previous.blockedByPeer])!==JSON.stringify([detail.chat.state,detail.chat.blockedByMe,detail.chat.blockedByPeer]);chatState.current=detail.chat;if(changed){const scroller=$('#chat-messages'),bottom=nearChatBottom(scroller),oldTop=scroller?.scrollTop||0;const reconciled=reconcileChatMessages(chatState.messages,detail.messages,chatState.olderCursor,detail.olderCursor);chatState.messages=reconciled.messages;chatState.olderCursor=reconciled.olderCursor;if(scroller){scroller.innerHTML=chatMessagesHTML();scroller.scrollTop=bottom?scroller.scrollHeight:oldTop;}}if(statusChanged||force){$('#chat-status').innerHTML=chatStatusHTML(detail.chat);const block=$('[data-action="chat-block"]');if(block)block.textContent=detail.chat.blockedByMe?'取消屏蔽':'屏蔽';updateChatControls();}if(detail.chat.unread)await markChatRead(id);if($('#chat-list'))$('#chat-list').innerHTML=chatListHTML();if($('#chat-list-error'))$('#chat-list-error').textContent='';}catch(e){if(generation!==chatState.generation)return;const target=$('#chat-list-error');if(target)target.textContent=e.message+' 将自动重试，也可以重新加载。';}}
function startChatPolling(){clearTimeout(chatState.timer);if(chatRouteId()===null||!state.user||document.hidden)return;const generation=chatState.generation;chatState.timer=setTimeout(async()=>{if(generation!==chatState.generation)return;await refreshChats();if(generation===chatState.generation)startChatPolling();},5000);}
function startChatForm(id,name){if(!state.user){needAccount();return;}if(id===state.user.id){toast('不能给自己发私聊');return;}modal('给'+(name||'创作者')+'发私聊邀请',`<form id="chat-start-form" class="chat-start-form"><p class="muted">说明你想聊什么。对方接受前，只能发这一条邀请。</p><label class="field">邀请内容<textarea name="body" required maxlength="2000" rows="5" placeholder="例如：看到你的作品，我也在做类似项目，想和你交流一下制作方法。"></textarea></label><p class="small-text muted">不要发送手机号、学校、住址或密码。</p><p class="form-error" role="alert"></p><div class="form-footer">${btn('取消','close')}<button class="btn primary" type="submit">发送邀请</button></div></form>`);$('#chat-start-form').onsubmit=e=>submit(e,async form=>{const body=form.elements.body.value.trim();if(!body)throw Error('先写一条邀请内容。');const d=await api('/chats','POST',{recipientId:id,body});close();toast('已打开对话，请查看邀请状态');nav('messages/'+encodeURIComponent(d.chat.id));});}
async function chatAction(name,el){const id=chatState.current?.id;if(name==='chat-retry'){await render();return;}if(!id)return;if(name==='chat-older'){if(chatState.loadingOlder||!chatState.olderCursor)return;chatState.loadingOlder=true;el.disabled=true;const generation=chatState.generation;try{const d=await api('/chats/'+encodeURIComponent(id)+'?before='+encodeURIComponent(chatState.olderCursor));if(generation!==chatState.generation)return;const scroller=$('#chat-messages'),height=scroller.scrollHeight,top=scroller.scrollTop;chatState.messages=[...new Map([...d.messages,...chatState.messages].map(m=>[m.seq,m])).values()].sort((a,b)=>a.seq-b.seq);chatState.olderCursor=d.olderCursor;scroller.innerHTML=chatMessagesHTML();scroller.scrollTop=top+scroller.scrollHeight-height;}catch(e){if($('#chat-error'))$('#chat-error').textContent=e.message;}finally{chatState.loadingOlder=false;if(el.isConnected)el.disabled=false;}return;}el.disabled=true;try{await api('/chats/'+encodeURIComponent(id)+(name==='chat-accept'?'/accept':'/block'),'POST',name==='chat-accept'?{}:{blocked:!chatState.current.blockedByMe});await refreshChats(true);}catch(e){if($('#chat-error'))$('#chat-error').textContent=e.message;}finally{if(el.isConnected)el.disabled=false;}}
function bindChat(){const input=$('#chat-contact-search');if(input)input.oninput=()=>{clearTimeout(chatState.searchTimer);const searchSeq=++chatState.searchSeq,q=input.value.trim(),target=$('#chat-contact-results');if(!q){target.innerHTML='';return;}target.innerHTML='<p class="small-text muted">正在查找…</p>';chatState.searchTimer=setTimeout(async()=>{try{const d=await api('/chats/contacts?q='+encodeURIComponent(q));if(searchSeq!==chatState.searchSeq||chatRouteId()===null)return;target.innerHTML=d.users?.length?d.users.map(u=>`<button class="chat-contact" data-action="start-chat" data-id="${esc(u.id)}" data-name="${esc(u.name)}"><span class="avatar">${esc(String(u.name||'创作者').slice(0,1))}</span><strong>${esc(u.name)}</strong><span>发邀请 →</span></button>`).join(''):'<p class="small-text muted">没有找到公开创作者。请试试其他昵称。</p>';}catch(e){if(searchSeq===chatState.searchSeq)target.innerHTML='<p class="chat-inline-error">'+esc(e.message)+' 请重新输入昵称重试。</p>';}},300);};const form=$('#chat-composer');if(form){const body=form.elements.body;body.oninput=()=>{if(chatState.current)chatState.drafts.set(chatState.current.id,body.value);updateChatControls();};form.onsubmit=async e=>{e.preventDefault();const id=chatState.current?.id,value=body.value.trim();const sender=state.user?.id,key=sender+'/'+id;if(!id||!value||!chatCanSend()||chatState.sendingKeys.has(key))return;chatState.sendingKeys.add(key);updateChatControls();$('#chat-error').textContent='';try{const d=await api('/chats/'+encodeURIComponent(id)+'/messages','POST',{body:value});if(state.user?.id!==sender)return;chatState.drafts.delete(id);if(chatRouteId()!==id||!form.isConnected)return;body.value='';chatState.current=d.chat;chatState.messages=[...new Map([...chatState.messages,d.message].map(m=>[m.seq,m])).values()].sort((a,b)=>a.seq-b.seq);$('#chat-messages').innerHTML=chatMessagesHTML();$('#chat-messages').scrollTop=$('#chat-messages').scrollHeight;await refreshChats();}catch(err){if(chatRouteId()===id&&form.isConnected&&$('#chat-error'))$('#chat-error').textContent=err.message;}finally{chatState.sendingKeys.delete(key);updateChatControls();}};updateChatControls();const scroller=$('#chat-messages');requestAnimationFrame(()=>{if(scroller?.isConnected)scroller.scrollTop=scroller.scrollHeight;});}startChatPolling();}
document.addEventListener('visibilitychange',()=>{if(document.hidden)stopChatPolling();else if(chatRouteId()!==null&&state.user){refreshChats().finally(startChatPolling);}});
async function render(){
stopChatPolling();const seq=++state.seq;$('#main').setAttribute('aria-busy','true');
const aliases={portfolio:'archive/works','discover/posts':'home','discover/creators':'creators','archive/posts':'my-posts','archive/profile':'profile','archive/notifications':'notifications','archive/bookmarks':'discover/bookmarks'};
let route=location.hash.slice(1)||'home';if(route==='main')route=state.route||'archive';state.route=aliases[route]||route;const [page,sub='']=state.route.split('?')[0].split('/'),fullMessages=page==='messages'&&new URLSearchParams(state.route.split('?')[1]||'').get('view')==='full';
if(page==='messages'&&!fullMessages){
if(messageState.full){messageState.full=false;if(messageState.baseContent){$('#main').replaceChildren(messageState.baseContent);messageState.baseContent=null;messageState.baseRendered=true;}else messageState.baseRendered=false;}
if(!messageState.baseRendered){const panelRoute=state.route;state.route=messageState.baseRoute;header();let background;try{background=await community();}catch(e){background=empty('首页暂时不可用',esc(e.message),'','chat');}if(seq!==state.seq)return;$('#main').innerHTML=background;bindPage();messageState.baseRendered=true;state.route=panelRoute;}
await showMessagePanel(page,sub,seq);document.title='对话 · 发现';return;
}
if($('#message-panel').open)$('#message-panel').close();$('#message-panel-body').replaceChildren();messageState.open=false;if(fullMessages&&!messageState.full){if(messageState.baseRendered){messageState.baseContent=document.createDocumentFragment();messageState.baseContent.append(...$('#main').childNodes);}messageState.full=true;}else if(!fullMessages){messageState.full=false;messageState.baseContent=null;}if(page!=='messages')messageState.baseRoute=state.route;header();let html,title='我的';
try{
if(page==='demo'){html=demoUI('detail',sub,decodeURIComponent(state.route.split('?')[0].split('/')[2]||''));title='演示内容';}
else if(page==='search'){html=await searchPage();title='搜索';}
else if(page==='home'){html=await community(sub);title='首页';}
else if(page==='messages'){$('#main').innerHTML='<div class="loading-state">正在加载对话…</div>';html=await messagesPage(sub,seq);title='对话';}
else if(page==='compose'){html=composePage();title='发帖子';}
else if(page==='creators'){html=await creators();title='创作者';}
else if(page==='archive'&&sub==='events'){html=personalEvents();title='我的参赛资料';}
else if(page==='discover'){html=await discover(sub);title=sub==='bookmarks'?'我的收藏':'作品';}
else if(page==='events'){html=events();title='比赛';}
else if(page==='profile'){html=profile();title='个人中心';}
else if(page==='login'){html=login(sub==='register');title='登录';}
else if(page==='privacy'){html=privacy();title='隐私说明';}
else if(page==='project'||page==='shared'){if(page==='shared'){const d=await api('/public/projects/'+encodeURIComponent(sub));state.feed.projects=[...state.feed.projects.filter(p=>p.id!==d.project.id),d.project];}html=await project(decodeURIComponent(sub),page==='shared');title='作品档案';}
else if(page==='public'){const d=await api(`/public/${encodeURIComponent(sub)}`),projects=d.projects||[],posts=d.posts||[];state.feed.projects=[...state.feed.projects.filter(p=>!projects.some(x=>x.id===p.id)),...projects];state.feed.posts=[...state.feed.posts.filter(p=>!posts.some(x=>x.id===p.id)),...posts];const publicName=d.name||d.profile?.name||d.author?.name||'创作者',publicId=d.author?.id||projects[0]?.author?.id||posts[0]?.author?.id||sub;html=heading(esc(publicName)+'的作品与经历','作品贡献由本人填写；内容公开审核不等于获奖或能力认证。',publicId!==state.user?.id?`<button class="btn small primary" data-action="start-chat" data-id="${esc(publicId)}" data-name="${esc(publicName)}">${icon('chat',17)} 私聊</button>`:'')+'<section><div class="section-heading"><h2>公开作品</h2></div>'+(projects.length?`<div class="work-grid">${projects.map((p,i)=>workCard(p,i,true)).join('')}</div>`:empty('暂时没有公开作品','可以先看看这位创作者分享的制作进展。','','folder'))+'</section><section><div class="section-heading"><h2>社区帖子</h2></div>'+(posts.length?posts.map(p=>postCard(p)).join(''):empty('暂时没有公开帖子','以后分享的制作进展和交流会出现在这里。','','chat'))+'</section>';title='公开档案';}
else if(page==='notifications'){html=await notifications(sub,seq);title='消息通知';}
else if(page==='my-posts'){html=myPostsPage();title='我的动态';}
else if(page==='prepare'||page==='credential'){html='<p><a href="#archive/events" class="text-button">← 返回我的参赛资料</a></p>'+ArchiveTools.render(page,{esc,toast,user:state.user||{profile:legacy.profile},projects:works()});title=page==='prepare'?'参赛准备':'凭证草稿';}
else html=archive(['works','files','history'].includes(sub)?sub:'');
}catch(e){html=empty('暂时没能打开这一页',esc(e.message),btn('重新加载','reload','primary'));}
if(seq!==state.seq)return;messageState.baseRendered=true;$('#main').innerHTML=html;$('#main').setAttribute('aria-busy','false');$('#main').classList.remove('page-enter');void $('#main').offsetWidth;$('#main').classList.add('page-enter');document.title=`${title} · 发现`;if(['prepare','credential'].includes(page))ArchiveTools.bind(page,{esc,toast,user:state.user||{profile:legacy.profile},projects:works()});bindPage();if(page==='compose')bindCompose();if(page==='messages')bindChat();
}
function modal(title,html){$('#modal-title').textContent=title;$('#modal-body').innerHTML=html;if(!$('#modal').open)$('#modal').showModal();}
function close(){ $('#modal').close(); }
function needAccount(allowLocal=false){if(state.user||(allowLocal&&state.local))return true;modal('先选择保存方式',`<p class="muted">登录后，资料保存在服务器；本机试用只能保存作品文字，不能上传附件或发布动态。</p><div class="form-footer">${btn('本机试用','local')}<a class="btn primary" href="#login" data-close>登录账号</a></div>`);return false;}
async function submit(event,fn){event.preventDefault();const form=event.currentTarget,button=form.querySelector('[type=submit]');if(button.disabled)return;const label=button.textContent;button.disabled=true;button.textContent='正在保存…';const error=form.querySelector('.form-error');error.textContent='';try{await fn(form);}catch(e){error.textContent=e.message;}finally{if(button.isConnected){button.disabled=false;button.textContent=label;}}}
function workForm(id){if(!needAccount(true))return;const p=works().find(p=>p.id===id)||{};modal(id?'编辑作品档案':'新建作品档案',`<form id="work-form"><div class="form-grid">${field('作品名称','title',p.title,{required:true,max:120,full:true})}${field('一句话介绍：帮谁解决什么问题','summary',p.summary,{required:true,area:true,full:true,max:2000})}${field('使用的工具与技能','tech',p.tech)}${field('我负责的部分','role',p.role)}${field('作品链接','url',p.url,{type:'url',help:'保存网页、代码仓库或视频的网址。'})}${field('比赛名称（选填，本人记录）','event',p.event,{help:'不等于主办方确认。'})}<label class="field">作品状态<select name="status">${['灵感阶段','进行中','已完成'].map(s=>`<option ${p.status===s?'selected':''}>${s}</option>`).join('')}</select></label><label class="field">谁可以看到<select name="visibility" ${state.user?'':'disabled'}><option value="private">仅自己</option><option value="public" ${p.visibility==='public'?'selected':''}>提交公开（需审核）</option></select></label>${field('制作笔记（仅自己可见）','notes',p.notes,{area:true,full:true,max:6000})}</div><p class="small-text muted" style="margin-top:17px">公开时只展示作品介绍、个人贡献与链接，不展示附件和私人笔记。</p><p class="form-error" role="alert"></p><div class="form-footer">${btn('取消','close')}<button type="submit" class="btn primary">保存作品</button></div></form>`);$('#work-form').onsubmit=e=>submit(e,async form=>{const d=Object.fromEntries(new FormData(form));d.visibility=d.visibility||'private';if(d.url&&!safeURL(d.url))throw Error('链接需要以 https:// 或 http:// 开头。');if(state.user){await api(id?`/projects/${id}`:'/projects',id?'PUT':'POST',d);await refresh();}else{if(id)legacy.works[Number(id.split('-')[1])]=d;else legacy.works.push(d);saveLocal();}close();toast(d.visibility==='public'?'作品已保存，等待人工审核后公开':'作品已私密保存');nav('archive/works');});}
function uploadForm(projectId){if(!state.user){needAccount();return;}modal('上传资料文件',`<form id="upload-form"><div class="form-grid"><label class="field full">选择文件<input name="attachment" type="file" required accept=".jpg,.jpeg,.png,.webp,.pdf,.txt,.md"><small>图片、PDF、文字笔记，单个最多 10 MB。文件始终私密。</small></label><label class="field">资料类别<select name="category"><option>作品资料</option><option>参赛材料</option><option>制作笔记</option><option>其他</option></select></label><label class="field">关联作品<select name="projectId"><option value="">暂不关联</option>${state.projects.map(p=>`<option value="${p.id}" ${p.id===projectId?'selected':''}>${esc(p.title)}</option>`).join('')}</select></label></div><p class="form-error" role="alert"></p><div class="form-footer">${btn('取消','close')}<button type="submit" class="btn primary">上传并保存</button></div></form>`);$('#upload-form').onsubmit=e=>submit(e,async form=>{const f=form.elements.attachment.files[0];if(!f)throw Error('请选择文件。');if(f.size>10485760)throw Error('文件超过 10 MB，请压缩后重试。');const content=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result.split(',')[1]);r.onerror=()=>reject(Error('未能读取文件'));r.readAsDataURL(f);});await api('/files','POST',{name:f.name,content,category:form.elements.category.value,projectId:form.elements.projectId.value||null});await refresh();close();toast('文件已保存，只有你可以下载');nav('archive/files');});}
function postForm(){if(!state.user){needAccount();return;}nav('compose');}
function myPostsPage(){return '<div class="page-layout"><div class="main-column personal-content">'+profileOverview()+myTabs('posts')+'<div class="section-heading"><div><h2>我发的帖子</h2><p class="small-text muted">待审核与未通过的帖子仅你自己可见。</p></div>'+btn('发帖子','new-post','small primary')+'</div>'+(state.posts.length?state.posts.map(p=>postCard(p,true)).join(''):empty('还没有发过帖子','分享进展、提问或找伙伴，提交后在这里查看审核状态。',btn('写第一条帖子','new-post','primary'),'chat'))+'</div>'+personalAside()+'</div>';}
function composePage(){if(!state.user)return heading('发帖子','登录后分享进展、提问或寻找伙伴。')+empty('先登录，再参与交流','本机试用不能发布帖子。','<a class="btn primary" href="#login">登录账号</a>','chat');if(composeState.owner!==state.user.id)resetCompose();if(composeState.projectId&&!state.projects.some(p=>p.id===composeState.projectId))composeState.projectId='';const names={update:'作品进展',question:'提问交流',team:'寻找伙伴'};return '<p class="compose-back"><a class="text-button" href="#home">← 返回首页</a></p>'+heading('发帖子','写下实际进展、具体问题，或你想找的伙伴。')+`<div class="compose-layout"><form id="post-form" class="compose-editor"><fieldset class="compose-kind-tabs"><legend class="sr-only">内容类型</legend>${Object.entries(names).map(([kind,label])=>`<label><input type="radio" name="kind" value="${kind}" ${composeState.kind===kind?'checked':''}><span>${label}</span></label>`).join('')}</fieldset><label class="field compose-body">帖子内容<textarea id="post-body" name="body" required minlength="3" maxlength="2000" rows="12" placeholder="第一行写清你想分享什么。\n\n后面可以补充：做到哪一步、遇到了什么问题、需要哪种帮助。">${esc(composeState.body)}</textarea></label><div class="compose-editor-footer"><label class="field">关联自己的作品（选填）<select name="projectId" aria-label="关联自己的作品（选填）"><option value="">不关联作品</option>${state.projects.map(p=>`<option value="${esc(p.id)}" ${composeState.projectId===p.id?'selected':''}>${esc(p.title)}</option>`).join('')}</select></label><span class="small-text muted"><span id="post-count">${composeState.body.length}</span> / 2000</span></div><p class="compose-save-note small-text muted">未提交的内容会在当前页面会话中保留，刷新或退出账号会清空。</p><p class="form-error" role="alert"></p><div class="form-footer"><a class="btn" href="#home">稍后再写</a><button type="submit" class="btn primary">提交公开审核</button></div></form><aside class="compose-tips"><section class="card tight compose-preview"><div class="section-heading"><h3>帖子预览</h3><span class="tag">尚未发布</span></div><div class="compose-preview-head"><span class="avatar">${esc((personal().name||'我').slice(0,1))}</span><div><strong>${esc(personal().name||'我')}</strong><small id="post-kind-preview">${names[composeState.kind]}</small></div></div><div id="post-preview-body" class="compose-preview-body"></div><div id="post-project-preview" class="small-text muted"></div></section><section class="card tight"><h3>发布前看一眼</h3><p class="profile-blurb">内容审核通过后才会公开，提交后到“我的动态”查看状态。</p><p class="small-text muted">关联作品不会自动公开。不要填写手机号、学校、住址或密码。</p></section></aside></div>`;}
function bindCompose(){const form=$('#post-form');if(!form)return;const body=form.elements.body,kind=()=>form.querySelector('[name="kind"]:checked').value;const preview=()=>{composeState.body=body.value;composeState.kind=kind();composeState.projectId=form.elements.projectId.value;$('#post-count').textContent=body.value.length;$('#post-kind-preview').textContent={update:'作品进展',question:'提问交流',team:'寻找伙伴'}[composeState.kind];const lines=body.value.trim().split('\n'),lead=lines.shift()||'你的帖子内容会显示在这里';$('#post-preview-body').innerHTML='<strong>'+esc(lead)+'</strong>'+(lines.join('\n')?'<p>'+esc(lines.join('\n'))+'</p>':'');const associated=state.projects.find(p=>p.id===composeState.projectId);$('#post-project-preview').textContent=associated?'关联作品：'+associated.title+(associated.review==='approved'&&associated.visibility==='public'?'':'（暂未公开）'):'';};form.oninput=preview;form.onchange=preview;preview();form.onsubmit=e=>submit(e,async current=>{const sender=state.user?.id;if(!sender)throw Error('请先登录账号。');const d={kind:kind(),projectId:current.elements.projectId.value||null,body:current.elements.body.value.trim()};if(d.body.length<3)throw Error('帖子至少写 3 个字。');await api('/posts','POST',d);if(state.user?.id!==sender)return;resetCompose();await refresh();toast('帖子已提交，在我的动态查看审核状态');nav('my-posts');});}


function download(name,data){const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);}
function confirm(title,message,fn){modal(title,`<p class="muted">${message}</p><p class="form-error" role="alert"></p><div class="form-footer">${btn('取消','close')}<button class="btn danger" id="confirm-action">确认${title}</button></div>`);$('#confirm-action').onclick=async e=>{e.currentTarget.disabled=true;try{await fn();close();toast('操作已完成');render();}catch(err){$('#modal-body .form-error').textContent=err.message;$('#confirm-action').disabled=false;}};}
function importLegacy(){modal('发现旧浏览器作品',`<p class="muted">当前浏览器有 ${legacy.works.length} 件作品。可以复制到这个账号，全部按私密保存；原本机记录仍保留。</p><p class="form-error" role="alert"></p><div class="form-footer">${btn('稍后再说','close')}<button class="btn primary" id="import-confirm">复制到当前账号</button></div>`);$('#import-confirm').onclick=async e=>{e.currentTarget.disabled=true;try{let n=0;for(const p of legacy.works){if(state.projects.some(w=>w.title===p.title&&w.summary===p.summary))continue;const d=await api('/projects','POST',{title:p.title||'未命名作品',summary:p.summary||'待补充',tech:p.tech||'',role:p.role||'',event:p.event||'',url:safeURL(p.url),status:p.status||'进行中',notes:p.notes||'',visibility:'private'});state.projects.push(d.project);n++;}await refresh();close();toast(`已复制 ${n} 件作品，原本机数据仍保留`);render();}catch(err){$('#modal-body .form-error').textContent=err.message;$('#import-confirm').disabled=false;}};}
function bindPage(){const cs=$('#creator-search');if(cs)cs.oninput=()=>{const q=cs.value.toLowerCase(),authors=publicAuthors().filter(a=>[...state.feed.projects,...state.feed.posts].some(p=>p.author?.id===a.id&&[a.name,p.tech,p.title,p.role,p.body].join(' ').toLowerCase().includes(q)));const examples=demoUI('creatorCards',q);$('#creator-results').innerHTML=authors.length||examples?authors.map(creatorCard).join('')+examples:empty('没有找到匹配的创作者','换一个昵称、作品或技能试试看。','','person');};const s=$('#work-search'),f=$('#work-filter');if(s){const filter=()=>{const q=s.value.toLowerCase();const found=works().filter(p=>(!f.value||p.status===f.value)&&`${p.title} ${p.summary} ${p.tech}`.toLowerCase().includes(q));$('#work-results').innerHTML=found.length?found.map(workRow).join(''):empty('没有找到匹配的作品','换一个关键词或状态试试看。');};s.oninput=filter;f.onchange=filter;}const ds=$('#discover-search');if(ds)ds.oninput=()=>{const q=ds.value.toLowerCase();const found=state.feed.projects.filter(p=>`${p.title} ${p.tech} ${p.summary} ${p.author?.name}`.toLowerCase().includes(q));const examples=demoUI('projectCards',q);$('#discover-results').innerHTML=found.length||examples?found.map((p,i)=>workCard(p,i,true)).join('')+examples:empty('没有找到匹配的作品','换一个关键词试试看。');};
if($('#auth-form'))$('#auth-form').onsubmit=e=>submit(e,async form=>{const d=await api(form.dataset.register==='true'?'/auth/register':'/auth/login','POST',Object.fromEntries(new FormData(form)));resetChatSession();state.user=d.user;state.local=false;localStorage.removeItem('archive-local-mode');await refresh();toast('已登录，档案已载入');nav('archive');if(legacy.works.length)setTimeout(importLegacy,150);});
if($('#profile-form'))$('#profile-form').onsubmit=e=>submit(e,async form=>{const d=Object.fromEntries(new FormData(form));if(state.user){await api('/profile','PUT',d);await refresh();}else{legacy.profile=d;saveLocal();}toast('个人档案已保存');nav('archive');});}

function commentHTML(c){const own=c.author?.id===state.user?.id,known=publicAuthors().some(a=>a.id===c.author?.id),publicLink=own?'#profile':known?'#public/'+encodeURIComponent(c.author.id):'',author=`<span class="avatar tiny">${esc(String(c.author?.name||'创作者').slice(0,1))}</span><strong>${esc(c.author?.name||'创作者')}</strong>`,authorUI=publicLink?`<a class="comment-author" href="${publicLink}" data-close>${author}</a>`:`<span class="comment-author">${author}</span>`;return `<article class="comment-item"><div class="comment-meta">${authorUI}<small>${date(c.createdAt)}</small>${c.review&&c.review!=='approved'?`<span class="tag">${c.review==='pending'?'待审核，仅自己可见':'未通过审核，仅自己可见'}</span>`:''}</div><p class="comment-body">${esc(c.body)}</p></article>`;}
async function loadComments(id,list,error){if(!list||!error)return;const request=String(Number(list.dataset.requestSeq||0)+1);list.dataset.requestSeq=request;try{const d=await api('/comments?postId='+encodeURIComponent(id));if(!list.isConnected||list.dataset.requestSeq!==request)return;list.innerHTML=d.comments?.length?d.comments.map(commentHTML).join(''):'<p class="muted">还没有公开回复。可以说说你的想法。</p>';if(d.post){const p=state.feed.posts.find(p=>p.id===id);if(p)Object.assign(p,d.post);}if(error.isConnected)error.textContent='';}catch(e){if(list.dataset.requestSeq!==request)return;if(error.isConnected)error.textContent=e.message;if(list.isConnected)list.innerHTML=btn('重新加载回复','comment-retry','small',id);}}
function commentsForm(id){const p=state.feed.posts.find(p=>p.id===id);modal('帖子回复',`<p class="comment-post-preview">${esc(p?.body?.slice(0,160)||'查看帖子下的交流')}</p><div id="comment-list" class="comment-list" aria-live="polite"><p class="muted">正在加载回复…</p></div>${state.user?`<form id="comment-form" class="comment-form"><label class="field">写一条回复<textarea name="body" required maxlength="1000" rows="3" placeholder="分享你的想法，或补充一个具体建议。"></textarea></label><p class="small-text muted">回复审核后公开。不要填写私人联系方式。</p><p class="form-error" role="alert"></p><div class="form-footer"><button type="submit" class="btn primary">提交回复</button></div></form>`:'<p class="muted">登录后可以参与回复。</p><a class="btn primary" href="#login" data-close>登录账号</a><p id="comment-error" class="form-error" role="alert"></p>'}`);const list=$('#comment-list'),error=$('#comment-form .form-error')||$('#comment-error');loadComments(id,list,error);if(state.user)$('#comment-form').onsubmit=e=>submit(e,async form=>{const body=form.elements.body.value.trim();if(!body)throw Error('先写下想回复的内容。');await api('/comments','POST',{postId:id,body});form.elements.body.value='';toast('回复已提交，审核前仅你可见');await loadComments(id,list,error);});}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el)return;const actionName=el.dataset.action;if(!['toggle-post','start-chat','post-comments','comment-retry','chat-retry','chat-older','chat-accept','chat-block'].includes(actionName))return;e.preventDefault();e.stopImmediatePropagation();if(actionName==='toggle-post'){const id=el.dataset.id,p=[...state.feed.posts,...state.posts].find(p=>p.id===id);if(!p)return;expandedPosts.has(id)?expandedPosts.delete(id):expandedPosts.add(id);el.closest('.post-card').outerHTML=postCard(p,state.route==='my-posts');}else if(actionName==='start-chat')startChatForm(el.dataset.id,el.dataset.name);else if(actionName==='post-comments')commentsForm(el.dataset.id);else if(actionName==='comment-retry')loadComments(el.dataset.id,$('#comment-list'),$('#comment-form .form-error')||$('#comment-error'));else chatAction(actionName,el).catch(err=>toast(err.message));});
async function action(name,el){const id=el?.dataset.id;switch(name){case 'read-notifications':{const route=state.route;el.disabled=true;try{if(await markNotificationsRead()&&state.route===route)await render();}finally{if(el.isConnected)el.disabled=false;}break;}case 'open-notification':{const route=el.dataset.route,owner=state.user?.id,originRoute=state.route,originSeq=state.seq;try{await markNotificationsRead([id]);}catch{toast('未读状态暂未更新，仍可查看原内容');}if(state.user?.id===owner&&state.route===originRoute&&state.seq===originSeq&&route)nav(route);break;}case 'close':close();break;case 'open-messages':nav('messages');break;case 'close-messages':closeMessages();break;case 'new':modal('新建内容',`<div class="side-links"><button data-action="new-work"><span><strong>作品档案</strong><br><small class="muted">保存作品介绍与个人贡献</small></span>${icon('folder')}</button><button data-action="upload"><span><strong>资料文件</strong><br><small class="muted">私密上传截图、文档和笔记</small></span>${icon('file')}</button><button data-action="new-post"><span><strong>社区动态</strong><br><small class="muted">分享进展、提问或寻找伙伴</small></span>${icon('chat')}</button></div>`);break;case 'new-work':close();workForm();break;case 'edit-work':workForm(id);break;case 'upload':close();uploadForm(id);break;case 'new-post':close();postForm();break;case 'local':close();state.local=true;localStorage.setItem('archive-local-mode','1');nav('archive');toast('本机试用：资料只保存在当前浏览器');break;case 'reload':await refresh();render();break;case 'import':importLegacy();break;case 'export-menu':modal('导出我的档案',`<div class="side-links"><button data-action="export-html"><span><strong>作品展示页</strong><br><small class="muted">包含当前全部作品，生成独立 HTML 文件</small></span>${icon('download')}</button><button data-action="export-data"><span><strong>文字记录与附件清单</strong><br><small class="muted">附件需在资料文件里单独下载</small></span>${icon('file')}</button>${state.user&&legacy.works.length?'<button data-action="import">导入旧浏览器作品 →</button>':''}</div>`);break;case 'export-html':if(!works().length){toast('先添加一件作品，再导出展示页');return;}close();ArchiveTools.exportPortfolio(personal(),works());toast('作品页已导出，分享前请检查私人内容');break;case 'export-data':download('我的档案备份.json',state.user?await api('/export'):readLegacy());close();toast('文字记录已导出，附件需单独下载');break;case 'logout':await api('/auth/logout','POST',{});resetChatSession();Object.assign(state,{user:null,projects:[],files:[],posts:[],feed:{projects:[],posts:[]},local:false,usage:{used:0,limit:104857600}});localStorage.removeItem('archive-local-mode');toast('已退出账号');nav('archive');break;case 'delete-work':confirm('删除作品','作品文字和历史版本会被删除，不能撤销；上传的文件仍保留在资料库。',async()=>{if(id.startsWith('local-')){legacy.works.splice(Number(id.split('-')[1]),1);saveLocal();}else{await api(`/projects/${id}`,'DELETE');await refresh();}nav('archive/works');});break;case 'delete-file':confirm('删除文件','文件会永久删除，没有回收站。请先下载需要保留的副本。',async()=>{await api(`/files/${id}`,'DELETE');await refresh();});break;case 'delete-post':confirm('删除动态','这条动态及其点赞和收藏记录会被删除。',async()=>{await api(`/posts/${id}`,'DELETE');await refresh();});break;case 'like':case 'bookmark':if(!state.user){needAccount();return;}const p=state.feed.posts.find(p=>p.id===id);if(!p)return;el.disabled=true;try{const d=await api(`/posts/${id}/${name}`,'POST',{active:!(name==='like'?p.liked:p.bookmarked)});Object.assign(p,d.post);await render();}finally{if(el.isConnected)el.disabled=false;}break;}}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(el){e.preventDefault();action(el.dataset.action,el).catch(err=>toast(err.message));}if(e.target.closest('[data-close]'))close();});
$('#message-panel').addEventListener('cancel',e=>{e.preventDefault();closeMessages();});
$('#message-panel').addEventListener('click',e=>{if(e.target!==$('#message-panel'))return;const r=$('#message-panel').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeMessages();});
$('#modal').addEventListener('click',e=>{if(e.target!==$('#modal'))return;const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)close();});
let motion=localStorage.getItem('archive-motion')!=='off';function applyMotion(){document.body.classList.toggle('reduce-motion',!motion);$('#motion-button').textContent=`动效：${motion?'开':'关'}`;$('#motion-button').setAttribute('aria-pressed',String(motion));}applyMotion();$('#motion-button').onclick=()=>{motion=!motion;localStorage.setItem('archive-motion',motion?'on':'off');applyMotion();};
$('#global-search-form').onsubmit=e=>{e.preventDefault();const q=e.currentTarget.elements.q.value.trim();nav('search?q='+encodeURIComponent(q));};
window.addEventListener('hashchange',()=>{close();window.scrollTo({top:0,behavior:'instant'});render();});
(async()=>{try{state.ready=!!(await api('/status')).ready;const m=await api('/me');state.user=m.user;state.usage=m.usage||state.usage;await refresh();}catch{state.ready=false;}await render();})();
})();


